import createMiddleware from "next-intl/middleware";
import { routing } from "./i18n/routing";

// Next.js 16 renamed middleware.ts -> proxy.ts (the next-intl import path is
// unchanged). Handles locale negotiation + the `/` -> /<locale> redirect.
export default createMiddleware(routing);

export const config = {
	// Skip API routes, Next internals, extension-less metadata routes, and any
	// path with a dot (static files: favicon.ico, robots.txt, sitemap.xml,
	// *.png, ...). Everything else gets locale handling.
	//
	// The metadata routes are generated by app/icon*.tsx, app/apple-icon.tsx and
	// app/opengraph-image.tsx and live at the ROOT only. Without them here the
	// locale middleware 307-redirects /icon -> /en/icon, which 404s (there is no
	// [locale]/icon route) — that surfaced as two console errors per page in
	// Lighthouse and broke the og:image / icon fetches for real browsers.
	matcher:
		"/((?!api|trpc|_next|_vercel|(?:icon|icon1|icon2|apple-icon|opengraph-image)(?:/|$)|.*\\..*).*)",
};
